import { useRef, useMemo, useCallback } from 'react';

const useFlightDataProcessor = (flightData) => {
  // Sample raw response data for fallback
  const sampleRawData = useRef([
    {
      "originAirport": "LHR",
      "destinationAirport": "EWR",
      "date": "2025-03-28",
      "distance": 3459,
      "ID": "sample1",
      "source": "aeroplan",
      "YAvailable": true,
      "WAvailable": false,
      "JAvailable": true,
      "FAvailable": false,
      "YDirect": true,
      "WDirect": false,
      "JDirect": true,
      "FDirect": false,
      "YAirlines": "AC, LH, QK, UA",
      "WAirlines": "",
      "JAirlines": "UA",
      "FAirlines": "",
      "YDirectAirlines": "UA",
      "WDirectAirlines": "",
      "JDirectAirlines": "UA",
      "FDirectAirlines": "",
      "YMileageCost": "40000",
      "WMileageCost": "0",
      "JMileageCost": "80000",
      "FMileageCost": "0",
      "YTotalTaxes": 34639,
      "WTotalTaxes": 0,
      "JTotalTaxes": 55000,
      "FTotalTaxes": 0,
      "YDirectMileageCost": 40000,
      "WDirectMileageCost": 0,
      "JDirectMileageCost": 80000,
      "FDirectMileageCost": 0,
      "YDirectTotalTaxes": 35470,
      "WDirectTotalTaxes": 0,
      "JDirectTotalTaxes": 55000,
      "FDirectTotalTaxes": 0,
      "TaxesCurrency": "CAD"
    }
  ]);

  // Get enriched flight data with raw API information
  const getEnrichedFlightData = useCallback((routeCode, classCode, dateString, classData) => {
    // Safety check for inputs
    if (!routeCode || !classCode || !dateString || !classData) {
      return [];
    }

    // Ensure flights is an array
    const flights = Array.isArray(classData[`${classCode}Flights`]) 
      ? classData[`${classCode}Flights`] 
      : [];

    // If no flights, return empty array
    if (flights.length === 0) return [];

    // Check for raw data from the flightData prop
    const rawDataArray = flightData?.rawData || sampleRawData.current || [];

    // First get flights with raw data attached
    const flightsWithRawData = flights.map(flight => {
      // If rawData is already present, just return the flight
      if (flight.rawData) return flight;

      try {
        // Find matching raw flight data
        const [origin, destination] = routeCode.split('-');

        const raw = rawDataArray.find(rawFlight => {
          return (
            (rawFlight.ID === flight.id || !flight.id) &&
            rawFlight.date === dateString &&
            rawFlight.originAirport === origin && 
            rawFlight.destinationAirport === destination &&
            rawFlight[`${classCode}Available`]
          );
        });

        // Return flight with raw data attached
        return {
          ...flight,
          rawData: raw || null
        };
      } catch (error) {
        console.warn('Error finding raw flight data:', error);
        return flight;
      }
    }).filter(flight => flight.rawData !== null);

    return flightsWithRawData;
  }, [flightData]);

  // Filter flights based on provided filters
  const filterFlights = useCallback((flights, classCode, dateString, filters) => {
    // If no filters are provided, return all flights
    if (!filters) return flights;

    // Handle all possible filter property names and structures
    const directFilter = filters.directFilter !== undefined ? filters.directFilter : filters.direct;
    const sourceFilter = filters.sourceFilter;
    const airlinesFilter = filters.airlinesFilter;
    const pointsFilter = filters.pointsFilter;
    const dateFilter = filters.dateFilter;

    console.log("Applying filter with properties:", {
      direct: directFilter,
      hasSourceFilter: sourceFilter && sourceFilter.sources && sourceFilter.sources.length > 0,
      hasAirlinesFilter: airlinesFilter && airlinesFilter.airlines && airlinesFilter.airlines.length > 0,
      hasPointsFilter: pointsFilter !== null && pointsFilter !== undefined,
      hasDateFilter: dateFilter && dateFilter.length > 0
    });

    return flights.filter(flight => {
      const rawData = flight.rawData;
      if (!rawData) return false;

      // Apply direct filter (highest priority)
      if (directFilter === true && !rawData[`${classCode}Direct`]) {
        return false;
      }

      // Apply source filter
      if (sourceFilter && sourceFilter.sources && sourceFilter.sources.length > 0) {
        const isInFilter = sourceFilter.sources.includes(rawData.source);
        if (sourceFilter.mode === 'include' && !isInFilter) return false;
        if (sourceFilter.mode === 'exclude' && isInFilter) return false;
      }

      // Apply airlines filter
      if (airlinesFilter && airlinesFilter.airlines && airlinesFilter.airlines.length > 0) {
        // Get airlines for this class, based on direct filter
        const airlinesStr = directFilter
          ? rawData[`${classCode}DirectAirlines`] 
          : rawData[`${classCode}Airlines`];

        if (!airlinesStr) return false;

        const flightAirlines = airlinesStr.split(',').map(a => a.trim());
        const hasMatchingAirline = flightAirlines.some(airline => 
          airlinesFilter.airlines.includes(airline)
        );

        if (airlinesFilter.mode === 'include' && !hasMatchingAirline) return false;
        if (airlinesFilter.mode === 'exclude' && hasMatchingAirline) return false;
      }

      // Apply points filter
      if (pointsFilter) {
        const mileageCost = directFilter
          ? Number(rawData[`${classCode}DirectMileageCost`] || 0)
          : Number(rawData[`${classCode}MileageCost`] || 0);

        if (mileageCost < pointsFilter[0] || mileageCost > pointsFilter[1] || mileageCost === 0) return false;
      }

      // Apply date filter
      if (dateFilter && dateFilter.length > 0 && !dateFilter.includes(dateString)) {
        return false;
      }

      return true;
    });
  }, []);

  // Get unique segments from flight data
  const getUniqueSegments = () => {
    const rawData = flightData?.rawData || sampleRawData.current || [];
    const segments = new Set();

    rawData.forEach(flight => {
      const route = `${flight.originAirport}-${flight.destinationAirport}`;
      segments.add(route);
    });

    return Array.from(segments).sort();
  };

  // Get unique sources from flight data
  const getUniqueSources = () => {
    const rawData = flightData?.rawData || sampleRawData.current || [];
    const sources = new Set();

    rawData.forEach(flight => {
      if (flight.source) {
        sources.add(flight.source);
      }
    });

    return Array.from(sources).sort();
  };

  // Get unique airlines from flight data
  const getUniqueAirlines = () => {
    const rawData = flightData?.rawData || sampleRawData.current || [];
    const airlines = new Set();

    rawData.forEach(flight => {
      ['Y', 'W', 'J', 'F'].forEach(classCode => {
        const airlinesStr = flight[`${classCode}Airlines`] || '';
        if (airlinesStr) {
          airlinesStr.split(', ').forEach(airline => {
            if (airline) airlines.add(airline.trim());
          });
        }
      });
    });

    return Array.from(airlines).sort();
  };

  // Get points range for slider
  const getPointsRange = () => {
    const rawData = flightData?.rawData || sampleRawData.current || [];
    let min = Infinity;
    let max = 0;

    rawData.forEach(flight => {
      ['Y', 'W', 'J', 'F'].forEach(classCode => {
        const points = Number(flight[`${classCode}MileageCost`] || 0);
        if (points > 0) {
          min = Math.min(min, points);
          max = Math.max(max, points);
        }
      });
    });

    return [min === Infinity ? 0 : min, max];
  };

  // Apply all filter types (global, group-based, segment-based) with correct scope and priority
  const applyAllFilters = useCallback((flights, classCode, dateString, allFilters) => {
    if (!flights || flights.length === 0) return [];

    // Apply filters with correct priority order: GLOBAL > GROUP > SEGMENT

    // Extract different filter types
    const { globalFilters, groupFilters, segmentFilters } = allFilters || {};

    // Get route from the first flight
    const route = flights[0]?.rawData ? 
      `${flights[0].rawData.originAirport}-${flights[0].rawData.destinationAirport}` : 
      null;

    if (!route) return flights;

    const [origin, dest] = route.split('-');

    // Check if we have any active filters
    const hasGlobalFilters = globalFilters && 
      (globalFilters.directFilter || 
       (globalFilters.sourceFilter && globalFilters.sourceFilter.sources && globalFilters.sourceFilter.sources.length > 0) || 
       (globalFilters.airlinesFilter && globalFilters.airlinesFilter.airlines && globalFilters.airlinesFilter.airlines.length > 0) ||
       globalFilters.pointsFilter ||
       (globalFilters.dateFilter && globalFilters.dateFilter.length > 0));

    // Find applicable group filters
    const applicableGroupFilters = groupFilters && Object.entries(groupFilters)
      .filter(([id, filter]) => {
        // Check if this group filter applies to the current route
        let originMatches = false;
        let destMatches = false;

        // Handle different group filter structures
        if (filter.originFilter && filter.originFilter.airports) {
          originMatches = filter.originFilter.airports.includes(origin);
        } else if (filter.originAirports) {
          originMatches = filter.originAirports.includes(origin);
        }

        if (filter.destFilter && filter.destFilter.airports) {
          destMatches = filter.destFilter.airports.includes(dest);
        } else if (filter.destAirports) {
          destMatches = filter.destAirports.includes(dest);
        }

        return originMatches && destMatches;
      })
      .map(([id, filter]) => filter);

    // Find applicable segment filters
    const applicableSegmentFilters = segmentFilters && Object.entries(segmentFilters)
      .filter(([id, filter]) => {
        return Array.isArray(filter.segments) && filter.segments.includes(route);
      })
      .map(([id, filter]) => filter);

    // Check which filters apply to this route

    // If no applicable filters, return all flights
    if (!hasGlobalFilters && 
        (!applicableGroupFilters || applicableGroupFilters.length === 0) && 
        (!applicableSegmentFilters || applicableSegmentFilters.length === 0)) {
      return flights;
    }

    // Priority logic: GLOBAL > GROUP > SEGMENT
    // We process in that order, but if a higher priority filter applies,
    // we don't process the lower priority ones

    let filteredFlights = [...flights];

    // 1. First apply global filters - if they exist, they override all others
    if (hasGlobalFilters) {
      filteredFlights = filterFlights(filteredFlights, classCode, dateString, globalFilters);
      return filteredFlights;
    }

    // 2. If no global filters but group filters exist, apply those
    if (applicableGroupFilters && applicableGroupFilters.length > 0) {
      console.log("FOUND APPLICABLE GROUP FILTERS:", applicableGroupFilters.length);

      // Start with all flights
      let groupFilteredFlights = [];

      // Add debugging to understand the structure of group filters
      for (const groupFilter of applicableGroupFilters) {
        // Examine and log the structure of the group filter
        console.log('Group filter to apply:', JSON.stringify({
          directFilter: groupFilter.directFilter,
          direct: groupFilter.direct,
          originFilter: groupFilter.originFilter,
          destFilter: groupFilter.destFilter,
          originAirports: groupFilter.originAirports,
          destAirports: groupFilter.destAirports,
          sourceFilterLength: groupFilter.sourceFilter?.sources?.length,
          airlinesFilterLength: groupFilter.airlinesFilter?.airlines?.length,
          hasPointsFilter: groupFilter.pointsFilter !== null && groupFilter.pointsFilter !== undefined,
          dateFilterLength: groupFilter.dateFilter?.length
        }));

        // Before filtering, create a clean filter object
        const cleanFilter = {
          directFilter: getBooleanValue(groupFilter.directFilter) || getBooleanValue(groupFilter.direct),
          sourceFilter: groupFilter.sourceFilter,
          airlinesFilter: groupFilter.airlinesFilter,
          pointsFilter: groupFilter.pointsFilter,
          dateFilter: groupFilter.dateFilter
        };

        console.log("Cleaned group filter:", JSON.stringify(cleanFilter));

        const currentFilterResults = filterFlights(filteredFlights, classCode, dateString, cleanFilter);
        console.log(`Group filter result: ${currentFilterResults.length} flights passed`);

        // Add any new flights that pass this filter to our results
        groupFilteredFlights = [...groupFilteredFlights, ...currentFilterResults];
      }

      // Remove duplicates
      const flightIds = new Set();
      groupFilteredFlights = groupFilteredFlights.filter(flight => {
        if (!flight.rawData || !flight.rawData.ID) return false;
        if (flightIds.has(flight.rawData.ID)) return false;
        flightIds.add(flight.rawData.ID);
        return true;
      });

      if (groupFilteredFlights.length > 0) {
        return groupFilteredFlights;
      }
    }

    // 3. If no global or group filters but segment filters exist, apply those
    if (applicableSegmentFilters && applicableSegmentFilters.length > 0) {
      console.log("FOUND APPLICABLE SEGMENT FILTERS:", applicableSegmentFilters.length);

      // Start with all flights
      let segmentFilteredFlights = [];

      // Apply each applicable segment filter in order (earlier ones have higher priority if they conflict)
      for (const segmentFilter of applicableSegmentFilters) {
        // Examine and log the structure of the segment filter
        console.log('Segment filter to apply:', JSON.stringify({
          directFilter: segmentFilter.directFilter,
          direct: segmentFilter.direct,
          segments: segmentFilter.segments,
          sourceFilterLength: segmentFilter.sourceFilter?.sources?.length,
          airlinesFilterLength: segmentFilter.airlinesFilter?.airlines?.length,
          hasPointsFilter: segmentFilter.pointsFilter !== null && segmentFilter.pointsFilter !== undefined,
          dateFilterLength: segmentFilter.dateFilter?.length
        }));

        // Before filtering, create a clean filter object
        const cleanFilter = {
          directFilter: getBooleanValue(segmentFilter.directFilter) || getBooleanValue(segmentFilter.direct),
          sourceFilter: segmentFilter.sourceFilter,
          airlinesFilter: segmentFilter.airlinesFilter,
          pointsFilter: segmentFilter.pointsFilter,
          dateFilter: segmentFilter.dateFilter
        };

        console.log("Cleaned segment filter:", JSON.stringify(cleanFilter));

        const currentFilterResults = filterFlights(filteredFlights, classCode, dateString, cleanFilter);
        console.log(`Segment filter result: ${currentFilterResults.length} flights passed`);

        // Add any new flights that pass this filter to our results
        segmentFilteredFlights = [...segmentFilteredFlights, ...currentFilterResults];
      }

      // Remove duplicates
      const flightIds = new Set();
      segmentFilteredFlights = segmentFilteredFlights.filter(flight => {
        if (!flight.rawData || !flight.rawData.ID) return false;
        if (flightIds.has(flight.rawData.ID)) return false;
        flightIds.add(flight.rawData.ID);
        return true;
      });

      return segmentFilteredFlights;
    }

    // If we get here, no filters applied or no flights passed the filters
    return filteredFlights;
  }, [filterFlights]);

  // Create a filtered version of getEnrichedFlightData that applies filters
  const getFilteredFlightData = useCallback((routeCode, classCode, dateString, classData, filters) => {
    // First get the raw flights
    const flights = getEnrichedFlightData(routeCode, classCode, dateString, classData);

    // Then apply filters
    return applyAllFilters(flights, classCode, dateString, filters);
  }, [getEnrichedFlightData, applyAllFilters]);

  return {
    getEnrichedFlightData,
    getFilteredFlightData,
    getUniqueSegments,
    getUniqueSources,
    getUniqueAirlines,
    getPointsRange
  };
};

export default useFlightDataProcessor;
